-- 📚 꼭집 주거 사전 — 행복주택 최대 거주기간 — 고령자·주거급여수급자 20년 · 2026
-- 재계산 SQL(관리 API에서 그대로 실행 · 읽기만). 범위: 공고일 2026년 · 유형은 housing_type_map 표준값.
-- 확인 2026-10-13 · 실행 2.8초 · 결과:
-- {"anns": 29, "by_std": {"행복주택": 24, "행복주택(신혼희망)": 5}, "고령주거급여20": 7, "고령주거급여20_ex": ["2015122300020870", "2015122300020858", "2015122300020854"]}
with a as(select distinct on(x.announcement_id)x.announcement_id,x.supply_org org,coalesce(m.std_type,x.housing_type)std,extract(year from coalesce(x.announcement_date,x.created_at::date))::int yr from announcements x left join housing_type_map m on m.source_table='announcements' and m.source=x.source and m.housing_type=x.housing_type order by x.announcement_id,(x.source='LH')desc,x.created_at desc),y as(select p.announcement_id,regexp_replace(p.content_raw,'\s+',' ','g')t,coalesce(r.class_name,c.class_name)cls,a.org,a.std from announcement_policies p join a using(announcement_id) left join policy_row_classes r on r.policy_id=p.id and r.axis='standard' left join policy_category_classes c on c.category=p.category and c.axis='standard' where a.yr=2026)select json_build_object('anns',(select count(distinct announcement_id) from y where std in('행복주택','행복주택(신혼희망)') and cls='최대 거주기간·임대기간'),'by_std',(select json_object_agg(std,n) from(select std,count(distinct announcement_id)n from y where std in('행복주택','행복주택(신혼희망)') and cls='최대 거주기간·임대기간' group by 1)q),'고령주거급여20',(select count(distinct announcement_id) from y where std in('행복주택','행복주택(신혼희망)') and cls='최대 거주기간·임대기간' and t~'고령자\s*,?\s*주거급여\s*수급자\s*[/:]?\s*(최대\s*거주기간\s*:\s*)?20\s*년'),'고령주거급여20_ex',(select json_agg(i) from(select distinct announcement_id i from y where std in('행복주택','행복주택(신혼희망)') and cls='최대 거주기간·임대기간' and t~'고령자\s*,?\s*주거급여\s*수급자\s*[/:]?\s*(최대\s*거주기간\s*:\s*)?20\s*년' order by 1 desc limit 3)q))j;
